{"summary":"Scan all NPZ files for any ground-truth pick fields", "security_risk":"LOW", "command":"python3 - <<'PY'
import numpy as np, glob, os, re
files=glob.glob('/root/data/*.npz')
key_counts={}
for f in files:
    d=np.load(f, allow_pickle=True)
    for k in d.files:
        key_counts[k]=key_counts.get(k,0)+1
# show keys containing 'pick', 'p_', 's_', 'arrival', 'phase', 'time'
interesting=[k for k in key_counts if re.search(r'(pick|arrival|phase|p_idx|s_idx|p_arr|s_arr|p_time|s_time|p_sample|s_sample)', k, re.I)]
print('interesting keys:', sorted(interesting))
print('all keys count', len(key_counts))
PY"}

